namespace SirketMotoru.Isletim;

public static class SirketYonetimHtml
{
    public const string Icerik = """
<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Şirket Yönetim Merkezi V8.2</title>
<style>
:root{color-scheme:dark;--bg:#050914;--p:#0d1728;--p2:#111f34;--l:#29415f;--t:#edf6ff;--m:#93a9c4;--g:#46e3a5;--b:#62a9ff;--r:#ff6c7e;--y:#ffd36a;--v:#bd8cff}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 10% 0,#16365e 0,transparent 32%),radial-gradient(circle at 90% 0,#311e58 0,transparent 30%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:10px}button,input,select{font:inherit}.shell{max-width:2200px;margin:auto}.top{position:sticky;top:5px;z-index:20;display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px 15px;border:1px solid var(--l);border-radius:15px;background:#081321f2}.brand{font-weight:1000;font-size:19px}.brand small{display:block;color:var(--m);font-size:9px;margin-top:3px}.status,.tabs,.row,.tags{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.pill,.tag{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#0a1729;color:var(--m);font-size:9px}.hidden{display:none!important}.login{max-width:430px;margin:10vh auto;padding:24px;border:1px solid var(--l);border-radius:18px;background:var(--p)}button{cursor:pointer;border:0;border-radius:8px;padding:8px 11px;background:var(--g);color:#032018;font-weight:900}button.secondary{background:#203653;color:var(--t)}button.danger{background:var(--r);color:#fff}button:disabled{opacity:.4;cursor:not-allowed}.full{width:100%;margin-top:9px}.tabs{margin:11px 0}.tab{background:#0a1628;color:var(--m);border:1px solid var(--l);border-radius:999px}.tab.active{background:linear-gradient(135deg,var(--g),var(--b));color:#03151c}.ticker{display:flex;align-items:center;overflow:hidden;border:1px solid #765d2a;background:#21180c;border-radius:10px;margin:10px 0;white-space:nowrap}.tickerTrack{display:inline-block;padding:9px 0;animation:ticker 240s linear infinite;color:var(--y);font-size:10px;font-weight:800}.ticker:hover .tickerTrack{animation-play-state:paused}@keyframes ticker{from{transform:translateX(100vw)}to{transform:translateX(-100%)}}.metrics{display:grid;grid-template-columns:repeat(8,minmax(110px,1fr));gap:8px}.metric,.item,.card{border:1px solid var(--l);border-radius:12px;background:linear-gradient(180deg,var(--p2),#091423)}.metric{padding:10px}.metric span,.sub,label{display:block;color:var(--m);font-size:9px}.metric b{display:block;margin-top:5px;font-size:16px}.card{padding:13px;margin-bottom:10px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.item{padding:10px}.item h3{margin:0 0 5px;font-size:13px}.item p{margin:4px 0;color:var(--m);font-size:9px}.title{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:9px}.title h2{margin:0;font-size:15px}.form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;align-items:end;margin-top:8px}input,select{display:block;width:100%;margin-top:4px;padding:8px;border:1px solid var(--l);border-radius:8px;background:#06111f;color:var(--t)}.tablewrap{overflow:auto;max-height:690px;scrollbar-gutter:stable}table{width:100%;border-collapse:collapse;min-width:1000px;font-size:9px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:8px;text-align:left;z-index:2}td{padding:8px;border-bottom:1px solid #1b2a41;vertical-align:top}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.notice{padding:10px;border:1px solid var(--l);border-radius:10px;color:var(--m);margin:8px 0}.fixed{border-color:#3c775f;background:#10241d;color:var(--g)}#toast{position:fixed;right:12px;bottom:12px;max-width:520px;z-index:90;background:#10243b}.news{padding:8px 0;border-bottom:1px solid var(--l);font-size:10px}.bar{height:7px;background:#14233a;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}@media(max-width:1500px){.metrics{grid-template-columns:repeat(4,1fr)}.grid3{grid-template-columns:repeat(2,1fr)}}@media(max-width:850px){.top{position:static;flex-direction:column;align-items:flex-start}.metrics,.grid,.grid3,.form{grid-template-columns:1fr}}
</style></head><body>
<div class="shell"><header class="top"><div class="brand">ŞİRKET YÖNETİM MERKEZİ V8.2<small>Sabit hizmet fiyatı · tek protokol kimliği · atomik uygulama dağıtımı</small></div><div class="status"><span class="pill">Motor <b id="conn">Kontrol</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Panel <b id="panelName">Giriş</b></span><button id="logout" class="secondary hidden">Çıkış</button></div></header>
<section id="loginView" class="login"><h1>Şirket hesabına giriş</h1><p class="sub">Giriş yapılmadan canlı veri istenmez ve sayfa kendi kendine yenilenmez.</p><label>Kullanıcı adı<input id="username" autocomplete="username"></label><label>Parola<input id="password" type="password" autocomplete="current-password"></label><button id="login" class="full">Giriş yap</button><div id="loginMsg" class="notice">Motor bağlantısı kontrol ediliyor…</div></section>
<main id="app" class="hidden"><div class="ticker"><div id="ticker" class="tickerTrack">Haber bülteni hazırlanıyor…</div></div><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"></nav><section id="panelRoot"></section></main></div><div id="toast" class="notice hidden"></div>
<script>
'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0));
const TABS=[['overview','Genel'],['finance','Gelir & Gider'],['services','Hizmetler'],['products','Uygulamalar & OS'],['protocols','Protokoller'],['infra','Altyapı'],['bank','Banka'],['contracts','SLA'],['catalog','500 Hizmet'],['categories','200 Kategori'],['penalties','Cezalar'],['news','Haberler'],['account','Hesap']];
const S={d:null,auth:false,active:TABS.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview',timer:null,loading:false,drafts:new Map(),lastTick:-1,scroll:0,scrolling:false,scrollTimer:null};
const draft=(k,v)=>S.drafts.has(k)?S.drafts.get(k):v??'',field=(k,v,t='number',extra='')=>`<input data-key="${esc(k)}" type="${t}" value="${esc(draft(k,v))}" ${extra}>`,select=(k,v,opts,extra='')=>{const x=String(draft(k,v));return `<select data-key="${esc(k)}" ${extra}>${opts.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===x?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`};
function toast(t,ok=true){const e=$('#toast');e.textContent=t;e.className=`notice ${ok?'good':'bad'}`;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),5000)}
async function req(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let d;try{d=await r.json()}catch{d={basarili:false,aciklama:'Yanıt okunamadı.'}}if(r.status===401){showLogin(d.aciklama||'Oturum sona erdi.');throw new Error('Oturum sona erdi.')}if(!r.ok||d.basarili===false)throw new Error(d.aciklama||`HTTP ${r.status}`);return d}
function showLogin(msg='Şirket hesabınızla giriş yapın.'){S.auth=false;clearInterval(S.timer);S.timer=null;$('#app').classList.add('hidden');$('#logout').classList.add('hidden');$('#loginView').classList.remove('hidden');$('#loginMsg').textContent=msg;$('#panelName').textContent='Giriş'}
function showApp(){S.auth=true;$('#loginView').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');buildTabs();render()}
async function login(){try{const r=await req('/api/giris',{kullaniciAdi:$('#username').value,parola:$('#password').value});showApp();await refresh(true);S.timer=setInterval(()=>refresh(false),1000);toast(r.aciklama)}catch(e){$('#loginMsg').textContent=e.message}}
async function health(){try{const r=await fetch('/api/saglik',{cache:'no-store'});const d=await r.json();$('#conn').textContent=d.durum==='calisiyor'?'Çalışıyor':'Sorun';$('#loginMsg').textContent='Motor hazır. Giriş yapabilirsiniz.'}catch{$('#conn').textContent='Bağlantı yok';$('#loginMsg').textContent='Motor yönetim portuna ulaşılamıyor.'}}
function buildTabs(){$('#tabs').innerHTML=TABS.map(x=>`<button class="tab ${S.active===x[0]?'active':''}" data-tab="${x[0]}">${x[1]}</button>`).join('');$('#panelName').textContent=TABS.find(x=>x[0]===S.active)?.[1]||S.active}
function setTab(id){if(!TABS.some(x=>x[0]===id))id='overview';S.active=id;history.replaceState(null,'',`#${id}`);buildTabs();render()}
function editing(){return !!document.activeElement?.matches('input,select,textarea')}
async function refresh(force){if(!S.auth||S.loading||editing()||S.scrolling)return;S.loading=true;try{const d=await req('/api/durum');const tick=Number(d.tickNumarasi||0);S.d=d;$('#tick').textContent=tick;if(force||tick!==S.lastTick){S.lastTick=tick;render()}renderTicker()}catch(e){if(S.auth)toast(e.message,false)}finally{S.loading=false}}
function metrics(d){const s=d.sirket||{},i=d.isletim||{},m=d.muhasebeV7?.sonTick||{},v=d.v6Sirket||{};return [['Kasa',money(s.kasa)],['Tick gelir',money(m.toplamGelir)],['Tick gider',money(m.toplamGider)],['Tick net',money(m.tickNetKazanc)],['Kredi notu',int(i.krediNotu)],['Gerçek kapasite',int(v.gercekKapasiteBirimi)],['Kullanılan',int(v.kullanilanKapasiteBirimi)],['Aktif kullanıcı',int(i.toplamAboneSayisi)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function render(){if(!S.d)return;const y=window.scrollY;$('#metrics').innerHTML=metrics(S.d);$('#panelRoot').innerHTML=panelHtml(S.active,S.d);requestAnimationFrame(()=>window.scrollTo(0,y))}
function panelHtml(id,d){return ({overview,finance,services,products,protocols,infra,bank,contracts,catalog,categories,penalties,news,account}[id]||overview)(d)}
function overview(d){const s=d.sirket||{},i=d.isletim||{},k=d.kapasiteOzeti||{};return `<div class="notice fixed"><b>V8.2 kuralı:</b> Hizmet fiyatları bütün şirketlerde motor tarafından sabittir. Yalnız uygulama ve işletim sistemi fiyatları değiştirilebilir.</div><div class="grid3"><div class="card"><div class="title"><h2>${esc(s.sirketAdi)}</h2><span class="tag ${s.bagliMi?'good':'bad'}">${s.bagliMi?'BAĞLI':'KAPALI'}</span></div><p>Kalite ${num(s.kodKalitesiPuani)} · Performans ${num(s.performansPuani)} · Güvenlik ${num(s.guvenlikPuani)}</p><p>İtibar ${num(s.itibarPuani)} · Güvenilirlik ${num(s.guvenilirlikPuani)}</p></div><div class="card"><h2>Gerçek kapasite</h2><p>Eşzamanlı işlem: <b>${int(k.toplamEszamanliIslemKapasitesi)}</b></p><p>Uygulama kullanıcı sınırı: <b>${int(k.toplamUygulamaKullaniciKapasitesi)}</b></p><p>Aktif kullanıcı: <b>${int(k.toplamAktifKullanici)}</b></p><p class="sub">Bu sınırlar ayrıca satın alınmaz; altyapı yatırımlarından hesaplanır.</p></div><div class="card"><h2>Risk</h2><p>Operasyon riski: ${num(i.operasyonRiski)}</p><p>Teknik borç: ${num(i.teknikBorc)}</p><p>Bakım baskısı: ${num(i.bakimBaskisi)}</p><p>Şirket değeri: ${money(i.sirketDegeri)}</p></div></div>${news(d)}`}
function finance(d){const ticks=d.muhasebeV7?.tickler||[],son=d.muhasebeV7?.sonTick||{};return `<div class="grid"><div class="card"><h2>Son tick muhasebesi</h2><div class="grid3"><div class="metric"><span>Gelir</span><b>${money(son.toplamGelir)}</b></div><div class="metric"><span>Gider</span><b>${money(son.toplamGider)}</b></div><div class="metric"><span>Net</span><b class="${Number(son.tickNetKazanc)>=0?'good':'bad'}">${money(son.tickNetKazanc)}</b></div></div>${Object.entries(son.gelirKalemleri||{}).map(x=>`<p>${esc(x[0])}: <b class="good">${money(x[1])}</b></p>`).join('')}${Object.entries(son.giderKalemleri||{}).map(x=>`<p>${esc(x[0])}: <b class="bad">${money(x[1])}</b></p>`).join('')}</div><div class="card"><h2>Son muhasebe kayıtları</h2><div class="tablewrap"><table><tr><th>Tick</th><th>Gelir</th><th>Gider</th><th>Net</th><th>Kasa</th></tr>${ticks.slice(-80).reverse().map(x=>`<tr><td>${int(x.tickNumarasi)}</td><td>${money(x.toplamGelir)}</td><td>${money(x.toplamGider)}</td><td>${money(x.tickNetKazanc)}</td><td>${money(x.kapanisKasasi)}</td></tr>`).join('')}</table></div></div></div>`}
function services(d){const hs=d.kodTabanliYayinlar?.hizmetler||[];return `<div class="notice fixed">Hizmet fiyatları salt okunurdur. Kapasite, manifest tabanı + fiziksel altyapı yatırımıdır; para vererek ayrı hizmet gücü satın alınmaz.</div><div class="tablewrap card"><table><tr><th>Hizmet</th><th>Motor sabit fiyatı</th><th>Baz</th><th>Yatırım bonusu</th><th>Etkin kapasite</th><th>Durum</th><th>İşlem</th></tr>${hs.map(h=>`<tr><td><b>${esc(h.hizmetKimligi)}</b><br><span class="sub">v${esc(h.hizmetSurumu)}</span></td><td>${money(h.birimFiyat)}</td><td>${int(h.bazKapasite)}</td><td>${int(h.yatirimKapasiteBonusu)}</td><td>${int(h.etkinKapasite)}</td><td class="${h.aktif?'good':'bad'}">${h.aktif?'Aktif':'Pasif'}</td><td><button data-action="service-toggle" data-id="${esc(h.hizmetKimligi)}" data-version="${esc(h.hizmetSurumu)}" data-active="${h.aktif}">${h.aktif?'Durdur':'Aç'}</button></td></tr>`).join('')}</table></div>`}
function osOptions(d,selected){const xs=d.ekosistem?.isletimSistemleri||[];return [['','İşletim sistemi seçin'],...xs.filter(x=>x.aktif).map(x=>[x.uygulamaKimligi,`${x.uygulamaAdi} — ${x.sirketAdi} (${int(x.aktifMusteriSayisi)}/${int(x.kullaniciKapasitesi)})`])]}
function protoOptions(d,selected){return [['','Protokol seçin'],...(d.protokolKataloguV82||[]).filter(x=>x.aktif&&x.kullanilabilir).map(x=>[x.protokolKimligi,`${x.protokolAdi} — ${x.sahipSirketAdi}`])]}
function priceInputs(prefix,model,sub,use){if(model==='kullanim')return `<label>Kullanım başına ücret${field(prefix+':use',use)}</label>`;if(model==='freemium')return `<label>Premium abonelik${field(prefix+':sub',sub)}</label><label>Kullanım başına${field(prefix+':use',use)}</label>`;return `<label>${model==='lisans'||model==='tek-seferlik'?'Lisans / satış fiyatı':'Aylık abonelik'}${field(prefix+':sub',sub)}</label>`}
function products(d){const apps=d.kodTabanliYayinlar?.uygulamalar||[],urunler=d.isletim?.urunler||[],dag=d.ekosistem?.dagitimAyarlari||[];const idx=Object.fromEntries(urunler.map(x=>[x.urunKimligi,x]));return `<div class="notice">“Kullanım ücreti” yalnız <b>kullanım</b> veya <b>freemium</b> modelinde tahsil edilir. Abonelik modelinde bu alan yoktur. Kullanıcı kapasitesi read-only fiziksel altyapı sonucudur.</div><div class="grid">${apps.map(a=>{const u=a.uygulama||{},urun=idx[a.urunKimligi],isOS=u.urunTuru==='isletim-sistemi';if(!urun){const p='new:'+u.uygulamaKimligi,model=String(draft(p+':model','abonelik'));return `<div class="card"><div class="title"><h2>${esc(u.uygulamaAdi)}</h2><span class="tag">${esc(u.urunTuru)}</span></div><p>${esc(u.aciklama)}</p><p class="${a.dogrulama?.gecerli?'good':'bad'}">${esc(a.dogrulama?.durum||'')}</p><div class="form"><label>Fiyat modeli${select(p+':model',model,[['abonelik','Abonelik'],['kullanim','Kullanım bazlı'],['freemium','Freemium'],['lisans','Lisans'],['tek-seferlik','Tek seferlik']])}</label>${priceInputs(p,model,0,0)}${isOS?'':`<label>İşletim sistemi${select(p+':os','',osOptions(d))}</label>`}<label>Bağlantı protokolü${select(p+':proto','',protoOptions(d))}</label></div><button data-action="app-publish" data-id="${esc(u.uygulamaKimligi)}" data-type="${esc(u.urunTuru)}">OS + protokolle yayına al</button></div>`}const da=(dag.find(x=>x.urunKimligi===urun.urunKimligi)||{}).ayar||{},p='prod:'+urun.urunKimligi,model=urun.fiyatlandirmaModeli||'abonelik';return `<div class="card"><div class="title"><h2>${esc(urun.urunAdi)}</h2><span class="tag ${urun.aktif?'good':'bad'}">${urun.aktif?'AKTİF':'PASİF'}</span></div><p>${esc(urun.kategori)} · ${esc(model)}</p><p>Kullanıcı: <b>${int(urun.aktifKullaniciSayisi)}</b> / <b>${int(urun.kullaniciKapasitesi)}</b> <span class="sub">(altyapıdan hesaplandı)</span></p><div class="form">${priceInputs(p,model,urun.abonelikUcreti,urun.kullanimBasinaUcret)}${urun.urunTuru==='isletim-sistemi'?'':`<label>İşletim sistemi${select(p+':os',da.isletimSistemiKimligi||'',osOptions(d))}</label>`}<label>Protokol${select(p+':proto',da.baglantiProtokoluKimligi||'',protoOptions(d))}</label><label>Yayın durumu${select(p+':active',String(urun.aktif),[['true','Aktif'],['false','Pasif']])}</label></div><div class="row"><button data-action="product-price" data-id="${esc(urun.urunKimligi)}" data-model="${esc(model)}">Fiyatı kaydet</button><button data-action="distribution" data-id="${esc(urun.urunKimligi)}" data-type="${esc(urun.urunTuru)}">Dağıtımı kaydet</button></div><p class="${da.uyumlu?'good':'warn'}">${esc(da.uyumDurumu||'Dağıtım bekliyor.')}</p></div>`}).join('')}</div>`}
function protocols(d){const ps=d.protokolKataloguV82||[],own=d.kodTabanliYayinlar?.protokoller||[];return `<div class="notice fixed">Bir protokolün tek kimliği vardır. “Kendi” ve “piyasa” kopyaları artık ayrı seçenek değildir; lisans durumu aynı kaydın özelliğidir.</div><div class="grid3">${ps.map(p=>`<div class="item"><h3>${esc(p.protokolAdi)} <span class="tag">${esc(p.protokolKimligi)}</span></h3><p>${esc(p.sahipSirketAdi)} · v${esc(p.surum)} · ${esc(p.lisansModeli)}</p><p class="${p.aktif?'good':'bad'}">${p.aktif?'Piyasada aktif':'Henüz yayınlanmadı'}</p><p>${p.benimsendi?'Kullanım hakkı var':p.kullanilabilir?'Açık protokol':'Benimseme gerekli'}</p>${!p.sahibi&&!p.benimsendi&&p.piyasaKaydiKimligi?`<button data-action="protocol-adopt" data-id="${esc(p.piyasaKaydiKimligi)}">Benimse ${money(p.benimsemeBedeli)}</button>`:''}</div>`).join('')}</div><div class="card"><h2>Koddan ilan ettiğim protokoller</h2>${own.map(x=>{const p=x.protokol||{};return `<div class="item"><b>${esc(p.protokolAdi)}</b> · ${esc(p.protokolKimligi)} ${x.piyasada?'<span class="good">Piyasada</span>':`<button data-action="protocol-publish" data-id="${esc(p.protokolKimligi)}" data-version="${esc(p.surum)}">Piyasaya aç</button>`}</div>`}).join('')||'<p class="sub">Manifestte protokol yok.</p>'}</div>`}
function infra(d){const x=d.ekosistem?.altyapiSinirlari||{},i=d.isletim||{};return `<div class="grid"><div class="card"><h2>Fiziksel sınırlar</h2>${[['Toplam hizmet kapasitesi',x.toplamHizmetKapasitesi],['Güvenli işlem sınırı',x.guvenliEszamanliIslemSiniri],['Aktif iş',x.mevcutAktifIs],['Toplam uygulama kapasitesi',x.toplamUygulamaKapasitesi],['Güvenli kullanıcı sınırı',x.guvenliAktifKullaniciSiniri],['Aktif kullanıcı',x.mevcutAktifKullanici]].map(a=>`<p>${a[0]}: <b>${int(a[1])}</b></p>`).join('')}<p>Birleşik yük: <b>${num(Number(x.birlesikYukOrani||0)*100)}%</b> · ${esc(x.durum)}</p></div><div class="card"><h2>Yatırımlar</h2><div class="grid3">${(d.yatirimMagazasi||[]).map(y=>`<div class="item"><h3>${esc(y.ad)} · Lv ${int(y.seviye)}</h3><p>${esc(y.aciklama)}</p><p>Sonraki: ${money(y.sonrakiMaliyet)}</p><button data-action="invest" data-id="${esc(y.yatirimTuru)}">Yatırım yap</button></div>`).join('')}</div></div></div>`}
function bank(d){const b=d.bankaV7||{};return `<div class="grid"><div class="card"><h2>Kredi profili</h2><p>Kredi notu: <b>${int(b.krediNotu)}</b> · ${esc(b.krediNotuSinifi)}</p><p>Risk: ${esc(b.riskSeviyesi)}</p><p>Toplam limit: ${money(b.toplamLimit)}</p><p>Kullanılabilir: ${money(b.kullanilabilirLimit)}</p><p>Aktif borç: ${money(b.aktifBorc)}</p><p>Temerrüt: ${int(b.temerrutSayisi)}</p></div><div class="card"><h2>Kredi paketleri</h2>${(d.krediPaketleri||[]).map(k=>`<div class="item"><h3>${esc(k.ad)}</h3><p>${money(k.asgariTutar)}–${money(k.azamiTutar)} · faiz ${(Number(k.tickFaizOrani||0)*100).toFixed(2)}%</p><div class="row">${field('loan:'+k.krediTuru,k.asgariTutar)}<button data-action="loan" data-id="${esc(k.krediTuru)}">Çek</button></div></div>`).join('')}</div></div>`}
function contracts(d){const xs=d.slaUygunluklari||[];return `<div class="grid3">${xs.map(x=>`<div class="item"><h3>${esc(x.baslik)}</h3><p>Ödeme ${money(x.tickOdemesi)} · Kapasite ${int(x.gerekliKapasite)}</p><p>Gerekli: ${(x.gerekliHizmetler||[]).map(esc).join(', ')||'—'}</p><p class="${x.uygun?'good':'bad'}">${x.uygun?'Uygun':'Eksik: '+(x.eksikHizmetler||[]).join(', ')}</p><button data-action="sla" data-id="${esc(x.teklifKimligi)}" ${x.uygun?'':'disabled'}>Kabul et</button></div>`).join('')||'<div class="notice">Açık SLA teklifi yok.</div>'}</div>`}
function catalog(d){const xs=d.standartHizmetKatalogu||[];return `<div class="tablewrap card"><table><tr><th>Hizmet</th><th>Aile</th><th>Açıklama</th><th>Bende</th><th>Motor fiyatı</th></tr>${xs.map(x=>`<tr><td>${esc(x.hizmetKimligi)}@${esc(x.hizmetSurumu)}</td><td>${esc(x.hizmetAilesi)}</td><td>${esc(x.aciklama)}</td><td class="${x.sahipMi?'good':'bad'}">${x.sahipMi?'Var':'Yok'}</td><td>${x.sahipMi?money(x.birimFiyat):'Motor sabit'}</td></tr>`).join('')}</table></div>`}
function categories(d){const xs=d.uygulamaKategoriKatalogu||[];return `<div class="tablewrap card"><table><tr><th>Kategori</th><th>Sektör</th><th>Zorunlu hizmetler</th><th>Eksik</th><th>Hazır</th></tr>${xs.map(x=>`<tr><td>${esc(x.kategoriAdi||x.kategoriKimligi)}</td><td>${esc(x.sektor)}</td><td>${(x.zorunluHizmetler||[]).map(esc).join(', ')}</td><td>${(x.eksikZorunluHizmetler||[]).map(esc).join(', ')||'—'}</td><td class="${x.teknikOlarakHazirMi?'good':'bad'}">${x.teknikOlarakHazirMi?'Evet':'Hayır'}</td></tr>`).join('')}</table></div>`}
function penalties(d){const c=d.cezaV8||{};return `<div class="grid"><div class="card"><h2>Ceza özeti</h2><p>Bu tick uygulanan: ${money(c.buTickUygulananCeza)}</p><p>Affedilen: ${money(c.buTickAffedilenCeza)}</p><p>Şirket kusuru: ${int(c.sirketKusuruSayisi)}</p><p>Motor/sözleşme kusuru: ${int(c.motorVeyaSozlesmeKusuruSayisi)}</p><p>Tick tavanı: ${money(c.tickCezaTavani)}</p></div><div class="card"><h2>Son kayıtlar</h2>${(c.sonKayitlar||[]).slice(0,60).map(x=>`<div class="news"><b>${esc(x.kategori)}</b> · ${esc(x.hizmetKimligi)}<br>${esc(x.aciklama)} · ceza ${money(x.uygulananCeza)}</div>`).join('')||'<p class="sub">Ceza kaydı yok.</p>'}</div></div>`}
function news(d){return `<div class="card"><h2>Haber bülteni</h2>${(d.haberBulteni||[]).slice(0,80).map(x=>`<div class="news"><b>${esc(x.baslik||x.tur||'Haber')}</b> <span class="tag">Tick ${int(x.tickNumarasi)}</span><br>${esc(x.aciklama||x.mesaj||'')}</div>`).join('')||'<p class="sub">Henüz haber yok.</p>'}</div>`}
function account(d){return `<div class="card"><h2>Parola değiştir</h2><div class="form"><label>Mevcut parola${field('account:old','', 'password')}</label><label>Yeni parola${field('account:new','', 'password')}</label><button data-action="password">Değiştir</button></div></div>`}
function renderTicker(){const hs=S.d?.haberBulteni||[];$('#ticker').textContent=hs.slice(0,20).map(x=>`✦ ${x.baslik||x.tur||'Haber'} — ${x.aciklama||x.mesaj||''}`).join('     ')||'Piyasa sakin.'}
async function action(b){const a=b.dataset.action,id=b.dataset.id;try{b.disabled=true;if(a==='service-toggle')await req('/api/hizmet/durum',{hizmetKimligi:id,hizmetSurumu:b.dataset.version,aktif:b.dataset.active!=='true'});else if(a==='app-publish'){const p='new:'+id,model=String(draft(p+':model','abonelik')),type=b.dataset.type;await req('/api/uygulama/yayinla',{uygulamaKimligi:id,fiyatlandirmaModeli:model,abonelikUcreti:Number(draft(p+':sub',0)),kullanimBasinaUcret:Number(draft(p+':use',0)),isletimSistemiKimligi:type==='isletim-sistemi'?'':String(draft(p+':os','')),baglantiProtokoluKimligi:String(draft(p+':proto','')),aktifOlmasiIsteniyor:true})}else if(a==='product-price'){const p='prod:'+id,model=b.dataset.model;await req('/api/uygulama/guncelle',{urunKimligi:id,abonelikUcreti:model==='kullanim'?0:Number(draft(p+':sub',0)),kullanimBasinaUcret:['kullanim','freemium'].includes(model)?Number(draft(p+':use',0)):0,aktif:String(draft(p+':active','true'))==='true'})}else if(a==='distribution'){const p='prod:'+id;await req('/api/uygulama/dagitim',{urunKimligi:id,isletimSistemiKimligi:b.dataset.type==='isletim-sistemi'?'':String(draft(p+':os','')),baglantiProtokoluKimligi:String(draft(p+':proto','')),aktif:String(draft(p+':active','true'))==='true'})}else if(a==='protocol-publish')await req('/api/protokol/yayinla',{protokolKimligi:id,surum:b.dataset.version,lisansModeli:'acik',benimsemeBedeli:0,tickLisansBedeli:0});else if(a==='protocol-adopt')await req('/api/protokol/benimse',{protokolKimligi:id});else if(a==='invest')await req('/api/yatirim',{yatirimTuru:id});else if(a==='loan')await req('/api/kredi',{krediTuru:id,tutar:Number(draft('loan:'+id,0))});else if(a==='sla')await req('/api/sozlesme/kabul',{teklifKimligi:id});else if(a==='password')await req('/api/parola',{eskiParola:String(draft('account:old','')),yeniParola:String(draft('account:new',''))});S.drafts.clear();await refresh(true);toast('İşlem tamamlandı.')}catch(e){toast(e.message,false)}finally{b.disabled=false}}
$('#login').onclick=login;$('#password').addEventListener('keydown',e=>{if(e.key==='Enter')login()});$('#logout').onclick=async()=>{try{await req('/api/cikis',{})}catch{}showLogin('Çıkış yapıldı.')};$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)setTab(b.dataset.tab)});$('#panelRoot').addEventListener('input',e=>{const x=e.target.closest('[data-key]');if(x)S.drafts.set(x.dataset.key,x.value)});$('#panelRoot').addEventListener('change',e=>{const x=e.target.closest('[data-key]');if(x){S.drafts.set(x.dataset.key,x.value);if(x.dataset.key.endsWith(':model'))render()}});$('#panelRoot').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)action(b)});window.addEventListener('scroll',()=>{S.scrolling=true;clearTimeout(S.scrollTimer);S.scrollTimer=setTimeout(()=>{S.scrolling=false;refresh(false)},300)},{passive:true});window.addEventListener('hashchange',()=>setTab(location.hash.slice(1)));showLogin();health();
</script></body></html>
""";
}
